import{_ as l,C as n,o as s,c as d,j as t,a as o,E as r,a3 as i}from"./chunks/framework.CZBGEXos.js";const f=JSON.parse('{"title":"Alerts","description":"","frontmatter":{},"headers":[],"relativePath":"uk/tools/alerts.md","filePath":"uk/tools/alerts.md"}'),h={name:"uk/tools/alerts.md"};function c(u,a,m,p,b,g){const e=n("Screenshot");return s(),d("div",null,[a[0]||(a[0]=t("h1",{id:"alerts",tabindex:"-1"},[o("Alerts "),t("a",{class:"header-anchor",href:"#alerts","aria-label":'Permalink to "Alerts"'},"​")],-1)),a[1]||(a[1]=t("p",null,"Alerts стежить одразу за двома речами й показує їх однією стрічкою:",-1)),a[2]||(a[2]=t("ol",null,[t("li",null,[t("strong",null,"Відхилення цін"),o(" — той самий актив коштує по-різному на різних біржах просто зараз.")]),t("li",null,[t("strong",null,"Нові лістинги"),o(" — токен, який щойно почав торгуватися на доступній біржі.")])],-1)),r(e,{src:"alerts",alt:"Вікно Alerts із картками відхилень і карткою нового лістингу",caption:"Вікно Alerts"}),a[3]||(a[3]=i('<h2 id="як-читати-вікно" tabindex="-1">Як читати вікно <a class="header-anchor" href="#як-читати-вікно" aria-label="Permalink to &quot;Як читати вікно&quot;">​</a></h2><p>Картки впорядковані від найновіших, за часом першої появи. Картка тримає своє місце, поки її числа оновлюються, тож стрічка не перебудовується під вами, поки ви її читаєте.</p><h3 id="картка-відхилення" tabindex="-1">Картка відхилення <a class="header-anchor" href="#картка-відхилення" aria-label="Permalink to &quot;Картка відхилення&quot;">​</a></h3><ul><li><strong>Символ</strong> — клацніть, щоб скопіювати в буфер обміну; на мить покаже <code>Copied!</code>.</li><li><strong>Спред</strong> — живий максимальний розрив цін між біржами у відсотках.</li><li><strong>Легенда</strong> — по одному запису на кожну біржу, де є цей тікер: кольорова крапка, що відповідає його лінії на графіку, назва біржі та її обсяг. Наведення на запис показує точну ціну й обсяг тієї біржі.</li><li><strong>Міні-графік</strong> — по одній ціновій лінії на біржу, щоб було видно, чи розрив розширюється, звужується, чи тримається.</li></ul><h4 id="як-рахується-спред" tabindex="-1">Як рахується спред <a class="header-anchor" href="#як-рахується-спред" aria-label="Permalink to &quot;Як рахується спред&quot;">​</a></h4><p>Відсоток — це <code>(найвища ціна − найнижча ціна) ÷ найнижча ціна × 100</code>, узятий по всіх біржах, які зараз повідомляють цей тікер.</p><p>Ця цифра <strong>жива</strong>. Вона безперервно перераховується з тих самих біржових вебсокетів, що живлять лінії графіка, і оновлюється приблизно двічі на секунду — тобто показує поточний розрив, а не той, що був у момент спрацювання сповіщення.</p><div class="warning custom-block"><p class="custom-block-title">Спред не є гарантованим прибутком</p><p>Це різниця між двома котируваннями. Вона нічого не каже про те, чи змогли б ви на цьому поторгувати: глибина стакана, комісії, фандинг, час переказу й доступність виведення до розрахунку не входять, а видимий розрив може закритися раніше, ніж виконається ордер. Сприймайте це як сигнал подивитися, а не як результат.</p></div><p>Графік навмисно наближений зі щільними ціновими полями, бо розрив між лініями бірж зазвичай малий відносно ціни й у звичайному масштабі був би непомітним.</p><h3 id="картка-нового-лістингу" tabindex="-1">Картка нового лістингу <a class="header-anchor" href="#картка-нового-лістингу" aria-label="Permalink to &quot;Картка нового лістингу&quot;">​</a></h3><p>Картки лістингів виглядають інакше за картки відхилень: тег <strong>NEW</strong>, символ (також із копіюванням по кліку) і час лістингу. Вони ділять стрічку й той самий ліміт карток зі сповіщеннями про відхилення.</p><h2 id="налаштування" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h2><p>Відкрийте вкладку <strong>Alerts</strong> у головному вікні.</p><h3 id="display" tabindex="-1">Display <a class="header-anchor" href="#display" aria-label="Permalink to &quot;Display&quot;">​</a></h3><h4 id="max-cards" tabindex="-1">Max cards <a class="header-anchor" href="#max-cards" aria-label="Permalink to &quot;Max cards&quot;">​</a></h4><p>Скільки карток стрічка показує одночасно. Діапазон <strong>від 3 до 50</strong>, за замовчуванням 9.</p><p>Ліміт застосовується вже після того, як сповіщення про відхилення й лістинги об&#39;єднані та відсортовані, тож обидва типи змагаються за ті самі місця.</p><h4 id="chart-timeframe" tabindex="-1">Chart timeframe <a class="header-anchor" href="#chart-timeframe" aria-label="Permalink to &quot;Chart timeframe&quot;">​</a></h4><p>Інтервал свічок для цінових ліній усередині карток відхилень. Варіанти: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>. За замовчуванням <code>1m</code>.</p><p>Це змінює лише графік. На розрахунок спреду й на те, які сповіщення проходять, воно не впливає.</p><h3 id="alert-settings" tabindex="-1">Alert settings <a class="header-anchor" href="#alert-settings" aria-label="Permalink to &quot;Alert settings&quot;">​</a></h3><h4 id="minimum-decorrelation" tabindex="-1">Minimum decorrelation <a class="header-anchor" href="#minimum-decorrelation" aria-label="Permalink to &quot;Minimum decorrelation&quot;">​</a></h4><p>Спред, якого тікер має досягти, щоб створити сповіщення. Діапазон <strong>від 1% до 10%</strong> з кроком 0.5%, за замовчуванням 1%.</p><div class="info custom-block"><p class="custom-block-title">Сповіщення не зникають, коли розрив закривається</p><p>Щойно тікер перетнув поріг, він лишається у стрічці й продовжує оновлюватися, навіть якщо його живий спред згодом опуститься нижче мінімуму. Поріг керує тим, що <em>потрапляє</em> всередину, а не тим, що лишається.</p></div><h3 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h3><h4 id="alert-sound" tabindex="-1">Alert sound <a class="header-anchor" href="#alert-sound" aria-label="Permalink to &quot;Alert sound&quot;">​</a></h4><p>Відтворює звук при появі нового сповіщення про відхилення. За замовчуванням увімкнено.</p><h4 id="listing-alert-sound" tabindex="-1">Listing alert sound <a class="header-anchor" href="#listing-alert-sound" aria-label="Permalink to &quot;Listing alert sound&quot;">​</a></h4><p>Відтворює звук, коли залістовано новий токен. За замовчуванням увімкнено.</p><p>Обидва незалежні — можна лишити лістинги зі звуком, а відхилення беззвучними, або навпаки.</p><h3 id="volume-filter" tabindex="-1">Volume filter <a class="header-anchor" href="#volume-filter" aria-label="Permalink to &quot;Volume filter&quot;">​</a></h3><h4 id="enable-volume-filter" tabindex="-1">Enable volume filter <a class="header-anchor" href="#enable-volume-filter" aria-label="Permalink to &quot;Enable volume filter&quot;">​</a></h4><p>Фільтрує сповіщення про відхилення за обсягом торгів. За замовчуванням вимкнено.</p><div class="info custom-block"><p class="custom-block-title">Потрібні двоє</p><p>Щоб сповіщення про відхилення пройшло фільтр, <strong>щонайменше дві біржі</strong> мають перевищувати мінімальний обсяг. Це зроблено навмисно: ціновий розрив має сенс лише тоді, коли за обома його сторонами стоять реальні торги.</p></div><p>Цей фільтр діє тільки на сповіщення про відхилення. Сповіщення про нові лістинги за обсягом не фільтруються — щойно залістований токен не має значущої історії обсягів.</p><h4 id="minimum-volume" tabindex="-1">Minimum volume <a class="header-anchor" href="#minimum-volume" aria-label="Permalink to &quot;Minimum volume&quot;">​</a></h4><p>5-хвилинний обсяг у доларах, потрібний біржі, щоб її сторона відхилення зараховувалась. Діапазон <strong>від $10K до $1M</strong> з кроком $10K, за замовчуванням $10K.</p><p>Неактивний, поки не увімкнено фільтр обсягу.</p><h2 id="стрічка-ліквідаціи" tabindex="-1">Стрічка ліквідацій <a class="header-anchor" href="#стрічка-ліквідаціи" aria-label="Permalink to &quot;Стрічка ліквідацій&quot;">​</a></h2><p>Alerts може також вести живу стрічку <strong>примусових закриттів позицій</strong> — це окремий потік від карток відхилень і лістингів, показаний власною смугою поруч із ними.</p>',40)),r(e,{src:"liquidations",alt:"Стрічка ліквідацій, пришвартована праворуч у вікні Alerts",caption:"Стрічка ліквідацій, пришвартована праворуч"}),a[4]||(a[4]=i('<p>За замовчуванням вона <strong>вимкнена</strong>. Клієнт, який її не вмикав, взагалі не отримує повідомлень про ліквідації.</p><h3 id="як-читати-стрічку" tabindex="-1">Як читати стрічку <a class="header-anchor" href="#як-читати-стрічку" aria-label="Permalink to &quot;Як читати стрічку&quot;">​</a></h3><p>У заголовку написано <code>LIQUIDATIONS</code>, а поруч, коли щось надходило нещодавно, — поточна сума: <strong>скільки ліквідовано за останні 60 секунд</strong>.</p><p>Кожен рядок — одна подія, найновіші вгорі:</p><table tabindex="0"><thead><tr><th>Частина</th><th>Значення</th></tr></thead><tbody><tr><td>Час</td><td>Коли відбулося</td></tr><tr><td>Кольорова крапка</td><td>Яка біржа, у її власному кольорі</td></tr><tr><td>Тікер</td><td>Без суфікса <code>USDT</code> / <code>USDC</code></td></tr><tr><td>Сума</td><td>Номінал саме цієї ліквідації</td></tr></tbody></table><p>Смуга на тлі рядка масштабується за розміром, тож великі події видно, навіть не читаючи цифру. <strong>Клік по рядку копіює тікер.</strong></p><p>При наведенні подія розписана словами — біржа, <code>long liquidated → forced sell</code> або <code>short liquidated → forced buy</code>, кількість і ціна.</p><div class="warning custom-block"><p class="custom-block-title">Колір відповідає тиску, а не слову</p><p>Ліквідований <strong>лонг</strong> — це примусовий <strong>продаж</strong>; ліквідований <strong>шорт</strong> — примусова <strong>покупка</strong>. Стрічка забарвлює саме за цим результуючим тиском, так само як ромби ліквідацій у <a href="/manual/uk/customize/majors.html#ліквідаціі-—-ромби">шарі мажорів</a>.</p></div><p>Доки не надійшла перша подія, у стрічці написано <code>waiting…</code>, а не порожньо.</p><h3 id="як-пересунути-и-змінити-розмір" tabindex="-1">Як пересунути й змінити розмір <a class="header-anchor" href="#як-пересунути-и-змінити-розмір" aria-label="Permalink to &quot;Як пересунути й змінити розмір&quot;">​</a></h3><p><strong>Тягніть заголовок <code>LIQUIDATIONS</code></strong>, щоб пришвартувати стрічку до будь-якого краю — ліворуч, праворуч, зверху або знизу. Ліворуч і праворуч дають колонку рядків, зверху й знизу — горизонтальну смугу. За замовчуванням праворуч.</p><p>Щоб змінити розмір, тягніть роздільник між стрічкою й картками.</p><p>Якщо стиснути вікно достатньо сильно, стрічка сховається сама, замість того щоб витісняти картки сповіщень.</p><h3 id="налаштування-1" tabindex="-1">Налаштування <a class="header-anchor" href="#налаштування-1" aria-label="Permalink to &quot;Налаштування&quot;">​</a></h3><p>Відкрийте вкладку <strong>Alerts</strong> у головному вікні.</p>',15)),r(e,{src:"liquidations-settings",alt:"Налаштування ліквідацій у вкладці Alerts",caption:"Налаштування Alerts — ліквідації"}),a[5]||(a[5]=i('<h4 id="enable-liquidation-tape" tabindex="-1">Enable liquidation tape <a class="header-anchor" href="#enable-liquidation-tape" aria-label="Permalink to &quot;Enable liquidation tape&quot;">​</a></h4><p>Показує примусові закриття позицій у реальному часі. <strong>Вимкнено за замовчуванням</strong> — усе нижче не діє, поки це не увімкнено.</p><h4 id="minimum-size" tabindex="-1">Minimum size <a class="header-anchor" href="#minimum-size" aria-label="Permalink to &quot;Minimum size&quot;">​</a></h4><p>Розмір однієї ліквідації в доларах. Діапазон <strong>від $5 000 до $1 000 000</strong> з кроком $5 000, за замовчуванням $50 000.</p><p>$5 000 — це власний поріг сервера: меншого він не зберігає, тож мінімальне значення вже означає «геть усе, що є».</p><h4 id="minimum-24h-turnover" tabindex="-1">Minimum 24h turnover <a class="header-anchor" href="#minimum-24h-turnover" aria-label="Permalink to &quot;Minimum 24h turnover&quot;">​</a></h4><p>Ховає тонкі тікери за їхнім обігом за 24 години. Діапазон <strong>від $0 до $50M</strong> з кроком $1M, за замовчуванням 0 — показується як <code>off</code>, тобто без фільтрації.</p><div class="warning custom-block"><p class="custom-block-title">Ненульове значення ховає і невідомі тікери</p><p>Будь-який тікер, чий обіг за 24 години ще невідомий, теж буде прихований — не лише справді тонкі. На щойно відкритому вікні це може означати помітно менше подій, доки дані про обіг не надійдуть.</p></div><h4 id="blacklist" tabindex="-1">Blacklist <a class="header-anchor" href="#blacklist" aria-label="Permalink to &quot;Blacklist&quot;">​</a></h4><p>Тікери, які ніколи не показувати. Введіть тікер і натисніть <kbd>Enter</kbd>, щоб додати; <strong>Clear all</strong> очищає список.</p><p>Корисно для тих кількох тікерів, які ліквідуються постійно й інакше заполонили б усю стрічку.</p><h4 id="rows-kept" tabindex="-1">Rows kept <a class="header-anchor" href="#rows-kept" aria-label="Permalink to &quot;Rows kept&quot;">​</a></h4><p>Скільки подій тримає стрічка, перш ніж видаляти найстаріші. Діапазон <strong>від 20 до 300</strong> з кроком 20, за замовчуванням 100.</p><h4 id="liquidation-sound" tabindex="-1">Liquidation sound <a class="header-anchor" href="#liquidation-sound" aria-label="Permalink to &quot;Liquidation sound&quot;">​</a></h4><p>Відтворює звук при надходженні ліквідації. <strong>Вимкнено за замовчуванням.</strong></p><p>Зверніть увагу: він спрацьовує на <em>кожну</em> подію, що пройшла ваші фільтри — при низькому мінімальному розмірі на активному ринку це дуже багато звуку. Спершу підніміть <strong>Minimum size</strong>, і лише тоді вмикайте.</p><h2 id="пов-язане" tabindex="-1">Пов&#39;язане <a class="header-anchor" href="#пов-язане" aria-label="Permalink to &quot;Пов&#39;язане&quot;">​</a></h2><ul><li><a href="/manual/uk/tools/knives.html">Knives</a> — рухи цін на одній біржі замість розривів між біржами. Knives також показує значок <strong>NEW</strong> для свіжих лістингів на своїх картках тікерів.</li><li><a href="/manual/uk/tools/monitor.html">Monitor</a> — ранжований огляд ринку</li></ul>',18))])}const k=l(h,[["render",c]]);export{f as __pageData,k as default};
